using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Topology.Resolution;

internal sealed class RetractiveAttachmentDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Topology/Resolution/RetractiveAttachment.";
    private static AssessedProvenance Provenance => AssessedProvenance.FromRepo(
        LibraryNoteRef.Create("D5/L/Topology/retractive2026reviewed"));
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Classical arbitrary-set retractive attachment supplier; original Efimov KPI 0.",
        H("RetractiveAttachment"), Blocks(
            Paragraph(Text("Statements below are projected from the compiled Lean declarations with their complete actual telescopes. The scientific source and independent ordinary review are identified in the cited Library note; neither source-level review nor this exposition substitutes for kernel checking.")),
            Describe.Lean(DescribeId.Create("is-open-iff"), DeclarationHandle.Create(Owner + "is_open_iff"), H("Literal neighborhood topology"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("Space(t) is literally the disjoint union B plus Sigma i P(i). An open set has open component traces and at each included core point contains N(U,J), where U is open and J is a finite set of arbitrary indices. No countability restriction is imposed, and the index type may be empty. The maps t(i) retain their full dependence on the component point."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("compact-space"), DeclarationHandle.Create(Owner + "compact_space"), H("Compactness of the constructed topology"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("An open cover has a finite subcover on the continuous image of the compact core. The union W of that finite family contains every component outside one finite exceptional set: cover the core by the actual core neighborhoods in W and unite their exceptions. Compactness of each remaining component supplies its finite subcover. Compactness is proved from this topology, not supplied in a structure field."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hausdorff"), DeclarationHandle.Create(Owner + "hausdorff"), H("Hausdorff separation"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("Two core points separate by pullbacks of disjoint core opens. A core point and a component separate by omitting that component. Points in one component separate by its open images, and distinct components separate by their clopen ranges."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("core-closed-embedding"), DeclarationHandle.Create(Owner + "core_closed_embedding"), H("Actual closed core embedding"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("The literal core inclusion is continuous and injective. The core complement is open by the defining topology, and the actual continuous left inverse gives the embedding with the original core topology."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("component-clopen-embedding"), DeclarationHandle.Create(Owner + "component_clopen_embedding"), H("Actual compact clopen component embeddings"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("The literal component inclusion is continuous and injective with its original topology. Open subsets of a component are open in the carrier, and the complement of the entire component is N(B,{i}). Each component is therefore an actual compact clopen embedded copy."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("continuous-retraction"), DeclarationHandle.Create(Owner + "continuous_retraction"), H("The literal continuous retraction"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("collapse is identity on the literal core and t(i) on component i. The inverse image of U is exactly N(U,empty), so continuity follows for every given continuous attachment map. Neither constancy nor surjectivity is required."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("is-clopen-iff"), DeclarationHandle.Create(Owner + "is_clopen_iff"), H("Exact finite-defect clopen algebra"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("Write V for the inverse image along the literal core inclusion and H(i) for the component trace. A clopen H has clopen traces. The open agreement set (H intersect collapse inverse V) union (complement H intersect collapse inverse complement V) contains the whole core. Compactness gives finitely many exceptional components; all other traces equal t(i) inverse V. Conversely the clopen traces and that one finite exception set give open core neighborhoods for H and its complement. This is an equivalence for actual subsets, including empty traces."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("zero-dimensional"), DeclarationHandle.Create(Owner + "zero_dimensional"), H("A genuine clopen basis"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("At a core point refine its actual open core neighborhood by a core clopen and retain the finite omissions. The finite-defect theorem proves this basic set clopen. Inside a component use the compact clopen image of a component clopen. These sets form a clopen basis of the actual carrier."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("transverse-tendsto-iff"), DeclarationHandle.Create(Owner + "transverse_tendsto_iff"), H("Actual transverse convergence"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("For an injective natural sequence of component indices and arbitrary chosen points in those components, convergence in the literal carrier to a core point is equivalent to Filter.Tendsto of their actual attachment images. Necessity uses collapse. Sufficiency uses convergence in the core together with eventual avoidance of every finite omitted set."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("sequence-of-infinite-multiplicity"), DeclarationHandle.Create(Owner + "sequence_of_infinite_multiplicity"), H("A sequence from infinite actual multiplicity"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("The set multiplicity(t,b) is the actual set of indices i for which b lies in range(t(i)). Embed the natural numbers in this infinite set and choose a point in each actual fibre. The resulting literal component points are injective, converge to the literal core point b, and never equal that limit."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("eventually-eq-of-no-sequence"), DeclarationHandle.Create(Owner + "eventually_eq_of_no_sequence"), H("All convergent sequences in a sequence-free Hausdorff space"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("If the off-limit range is finite, its closed complement is a neighborhood of the limit and forces eventual equality. If infinite, enumerate distinct actual off-limit values and choose their original indices. These indices are injective and hence tend to infinity, yielding a convergent injective natural sequence, a contradiction."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("no-sequence-iff"), DeclarationHandle.Create(Owner + "no_sequence_iff"), H("Full sequence-free characterization"), StatementSource.FromLean(), Provenance, Blocks(Paragraph(Text("NoConvergentInjectiveSequence quantifies actual functions from the natural numbers, actual Function.Injective, and actual Filter.Tendsto to a neighborhood filter. The carrier has this property exactly when the core and every component have it and every actual core point has finite range multiplicity. For a component limit, the tail lies in its open embedded component. For a core limit, the collapse images eventually equal that point. Finite multiplicity and eventual avoidance of each fixed closed component leave no possible tail of an injective sequence. Empty index types are included. A limit occurring among the terms can occur at most once, and deleting that term gives the usual nontrivial-sequence convention."))), DescribeRole.Theorem))));
}
